from pathlib import Path

root = Path('build-src/MediAgenda_Android_v1')
base = root / 'app/src/main/java/com/mediagenda/app'
def replace_once(file: Path, old: str, new: str, label: str):
    s = file.read_text(encoding='utf-8')
    n = s.count(old)
    if n != 1:
        raise RuntimeError(f'v1.9.46 {label}: expected 1, found {n}')
    file.write_text(s.replace(old, new, 1), encoding='utf-8')

replace_once(base / 'data/HealthDocumentStore.kt', '    fun rename(document: HealthDocument, title: String) {', '    /** Archives an original PDF in the active user\'s Documents vault.\n     * Re-importing identical PDF bytes does not create duplicate entries.\n     * This is separate from OCR: the complete original PDF is kept.\n     * Returns true only when a new document was added.\n     */\n    fun archivePdfIfMissing(uri: Uri, title: String = suggestedName(uri)): Boolean {\n        if (mime(uri).first != "application/pdf") return false\n        fun sha256(input: java.io.InputStream): ByteArray {\n            val md = java.security.MessageDigest.getInstance("SHA-256")\n            val buffer = ByteArray(32768)\n            var size = 0L\n            input.use { stream ->\n                while (true) {\n                    val count = stream.read(buffer)\n                    if (count < 0) break\n                    size += count\n                    require(size <= maxBytes) { "O PDF ultrapassa 50 MB." }\n                    md.update(buffer, 0, count)\n                }\n            }\n            require(size > 0) { "O PDF está vazio." }\n            return md.digest()\n        }\n        val input = context.contentResolver.openInputStream(uri)\n            ?: throw IllegalStateException("Não foi possível abrir o PDF original.")\n        val incoming = sha256(input)\n        for (document in all()) {\n            if (document.mimeType != "application/pdf") continue\n            val stored = runCatching { file(document) }.getOrNull() ?: continue\n            if (!stored.isFile || stored.length() <= 0L || stored.length() > maxBytes) continue\n            val previous = runCatching { sha256(stored.inputStream()) }.getOrNull()\n            if (previous != null && previous.contentEquals(incoming)) return false\n        }\n        add(uri, title)\n        return true\n    }\n\n    fun rename(document: HealthDocument, title: String) {', 'archive-unique-pdf')
replace_once(base / 'MainActivity.kt', '                    if (renderer.pageCount == 0) throw IllegalStateException("PDF vazio")\n                    val pages = (0 until renderer.pageCount).map { "Página ${it+1}" }.toTypedArray()\n', '                    if (renderer.pageCount == 0) throw IllegalStateException("PDF vazio")\n                    // Importing a prescription/appointment PDF always archives the\n                    // COMPLETE ORIGINAL in the selected profile\'s Digital Documents.\n                    // The OCR renders only one page, but must not discard the PDF.\n                    val documentStore = com.mediagenda.app.data.HealthDocumentStore(\n                        this, activeProfileId)\n                    val added = documentStore.archivePdfIfMissing(\n                        uri, documentStore.suggestedName(uri))\n                    if (added) Toast.makeText(this,\n                        "PDF original guardado em Documentos Digitais.",\n                        Toast.LENGTH_LONG).show()\n                    val pages = (0 until renderer.pageCount).map { "Página ${it+1}" }.toTypedArray()\n', 'medication-agenda-archive-pdf')
replace_once(base / 'ClinicalLabsActivity.kt', '                runCatching{store.add(uri,name,dateRaw,mime,rawText,values)}\n                    .onSuccess{\n                        dialog.dismiss()\n', '                runCatching{store.add(uri,name,dateRaw,mime,rawText,values)}\n                    .onSuccess{\n                        if (mime == "application/pdf") {\n                            runCatching {\n                                com.mediagenda.app.data.HealthDocumentStore(\n                                    this,activeProfileId).archivePdfIfMissing(uri,name)\n                            }.onFailure { problem ->\n                                notify("Relatório guardado em Análises, mas não foi possível " +\n                                    "arquivar o PDF em Documentos Digitais: " + problem.message)\n                            }\n                        }\n                        dialog.dismiss()\n', 'clinical-lab-pdf')
replace_once(base / 'WorkMedicineActivity.kt', '                }.onSuccess{\n                    dialog.dismiss();temp?.delete();redraw()\n                    Toast.makeText(this,"Documento guardado.",Toast.LENGTH_LONG).show()\n                }.onFailure{message(it.message?:"Não foi possível importar.")}\n', '                }.onSuccess{\n                    // The occupational archive keeps its own original. Also index\n                    // PDFs in Digital Documents for this same user profile.\n                    runCatching {\n                        com.mediagenda.app.data.HealthDocumentStore(\n                            this, patientId).archivePdfIfMissing(uri,title)\n                    }.onFailure { problem ->\n                        message("Documento guardado em Medicina do Trabalho, mas " +\n                            "não foi possível arquivar o PDF: " + problem.message)\n                    }\n                    dialog.dismiss();temp?.delete();redraw()\n                    Toast.makeText(this,"Documento guardado.",Toast.LENGTH_LONG).show()\n                }.onFailure{message(it.message?:"Não foi possível importar.")}\n', 'work-medicine-archive-pdf')
